{"files":[{"path":"src/views/records/dateRules.js","content":"/** 两个录入入口共用日历日期校验，错误代码用于表单和导入行提示。 */
function localToday() {
  const now = new Date();
  const year = now.getFullYear();
  const month = String(now.getMonth() + 1).padStart(2, '0');
  const day = String(now.getDate()).padStart(2, '0');
  return `${year}-${month}-${day}`;
}

export function validateSurveyDate(value, today) {
  if (typeof value !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(value)) return 'INVALID_DATE';
  const parsed = new Date(`${value}T00:00:00.000Z`);
  if (Number.isNaN(parsed.valueOf()) || parsed.toISOString().slice(0, 10) !== value) return 'INVALID_DATE';
  const base = today === undefined ? localToday() : today;
  if (value > base) return 'FUTURE_DATE';
  return null;
}
"},{"path":"src/views/records/create.js","content":"import { validateSurveyDate } from './dateRules.js';

/** 新增失败返回字段错误；成功时保留调用者给出的其他字段。 */
export function createSurvey(input, today) {
  const error = validateSurveyDate(input.surveyDate, today);
  return error ? { ok: false, fieldErrors: { surveyDate: error } }
    : { ok: true, record: { ...input } };
}
"},{"path":"src/views/records/import.js","content":"import { validateSurveyDate } from './dateRules.js';

/** 导入保持按行部分成功；无效日期只影响所属行，不改变其他记录。 */
export function importSurveys(rows, today) {
  const inserted = [];
  const errors = [];
  rows.forEach((record, index) => {
    const code = validateSurveyDate(record.surveyDate, today);
    if (code) errors.push({ row: index + 1, field: 'surveyDate', code });
    else inserted.push({ ...record });
  });
  return { inserted, errors };
}
"},{"path":"src/views/records/dateRules.spec.js","content":"import assert from 'node:assert/strict';
import { test } from 'node:test';
import { createSurvey } from './create.js';
import { importSurveys } from './import.js';
import { validateSurveyDate } from './dateRules.js';

test('新增保留有效日历日期和其他字段', () => {
  const input = { id: 'synthetic-a', surveyDate: '2026-10-26', category: 'sample' };
  assert.deepEqual(createSurvey(input, '2026-10-27'), { ok: true, record: input });
});

test('导入按行返回无效日历日期，保留其他有效行', () => {
  const first = { id: 'synthetic-a', surveyDate: '2026-10-26' };
  assert.deepEqual(importSurveys([first, { surveyDate: '2026-02-30' }], '2026-10-27'), {
    inserted: [first], errors: [{ row: 2, field: 'surveyDate', code: 'INVALID_DATE' }],
  });
});

test('共用校验允许今天和过去，拒绝未来', () => {
  assert.equal(validateSurveyDate('2026-10-27', '2026-10-27'), null);
  assert.equal(validateSurveyDate('2026-10-26', '2026-10-27'), null);
  assert.equal(validateSurveyDate('2026-10-28', '2026-10-27'), 'FUTURE_DATE');
});

test('新增对未来日期返回字段错误', () => {
  assert.deepEqual(createSurvey({ surveyDate: '2026-10-28' }, '2026-10-27'), {
    ok: false, fieldErrors: { surveyDate: 'FUTURE_DATE' },
  });
});

test('导入中未来行失败且其他有效行成功并返回正确行号', () => {
  const first = { id: 'synthetic-a', surveyDate: '2026-10-26' };
  const third = { id: 'synthetic-c', surveyDate: '2026-10-27' };
  assert.deepEqual(importSurveys([first, { surveyDate: '2026-10-28' }, third], '2026-10-27'), {
    inserted: [first, third], errors: [{ row: 2, field: 'surveyDate', code: 'FUTURE_DATE' }],
  });
});
"}]}
